CREATE TABLE IF NOT EXISTS "LandingFootprint" ("id" TEXT PRIMARY KEY, "value" DOUBLE PRECISION NOT NULL, "suffix" TEXT NOT NULL DEFAULT '', "label" TEXT NOT NULL, "sublabel" TEXT NOT NULL, "sortOrder" INTEGER NOT NULL DEFAULT 0, "isActive" BOOLEAN NOT NULL DEFAULT true, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL);
CREATE INDEX IF NOT EXISTS "LandingFootprint_isActive_sortOrder_idx" ON "LandingFootprint"("isActive", "sortOrder");
CREATE TABLE IF NOT EXISTS "LandingJourneyMilestone" ("id" TEXT PRIMARY KEY, "period" TEXT NOT NULL, "title" TEXT NOT NULL, "tagline" TEXT NOT NULL, "description" TEXT NOT NULL, "iconName" TEXT NOT NULL DEFAULT 'MapPin', "sortOrder" INTEGER NOT NULL DEFAULT 0, "isActive" BOOLEAN NOT NULL DEFAULT true, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL);
CREATE INDEX IF NOT EXISTS "LandingJourneyMilestone_isActive_sortOrder_idx" ON "LandingJourneyMilestone"("isActive", "sortOrder");
INSERT INTO "LandingFootprint" ("id","value","suffix","label","sublabel","sortOrder","updatedAt") VALUES
('footprint-travellers',100,'+','Travellers','and counting',1,CURRENT_TIMESTAMP),('footprint-trips',15,'+','Trips Completed','across India',2,CURRENT_TIMESTAMP),('footprint-institutes',5,'','Institutes Collaborated','edu partnerships',3,CURRENT_TIMESTAMP),('footprint-rating',5,'/5','Customer Rating','average score',4,CURRENT_TIMESTAMP),('footprint-solo',10,'+','Solo Travellers','found their tribe',5,CURRENT_TIMESTAMP),('footprint-group',90,'+','Group Travellers','lifetime memories',6,CURRENT_TIMESTAMP) ON CONFLICT ("id") DO NOTHING;
INSERT INTO "LandingJourneyMilestone" ("id","period","title","tagline","description","iconName","sortOrder","updatedAt") VALUES
('journey-idea','Jan 2023','Idea Conceived','The spark.','Two wanderers with a stubborn belief that travel should feel more human and less like a package tour. Scribbled on a napkin in a Ziro dhaba.','Lightbulb',1,CURRENT_TIMESTAMP),('journey-first-trip','Mar 2023','First Trip Conducted','We just went.','Eight people, one valley, zero expectations. Arunachal Pradesh taught us everything we needed to know about building experiences that last.','MapPin',2,CURRENT_TIMESTAMP),('journey-first-traveler','May 2023','First Paying Traveler','Someone believed.','A stranger paid us real money to take them somewhere real. That trust became the foundation of Hangover Trails.','User',3,CURRENT_TIMESTAMP),('journey-community','Sep 2023','50 Travelers Milestone','A community formed.','Fifty stories and fifty homecomings. We knew then this was no longer a side project.','Users',4,CURRENT_TIMESTAMP),('journey-institutes','Jan 2024','Institute Collaborations','Education meets adventure.','Universities and colleges began trusting us with their students. Educational travel got a soul.','GraduationCap',5,CURRENT_TIMESTAMP),('journey-festivals','Aug 2024','Festival Partnerships','Culture came alive.','We partnered with India''s most raw and authentic festivals. Hangover Trails became a festival home.','Music2',6,CURRENT_TIMESTAMP),('journey-events','Feb 2025','Community Events','Beyond the trip.','Bonfires, meetups, and reunions made Hangover Trails a tribe beyond the trip.','Flame',7,CURRENT_TIMESTAMP) ON CONFLICT ("id") DO NOTHING;
